    "@semio-tech/compose-assets": "*",
    "@compose/ui": "*",
    "vite-plugin-singlefile": "*"
  }
}
```

### 5. **Python MCP Server - Main Implementation** - [compose/engine/main.py](compose/engine/main.py)

#### Session State Management (lines 1944-1952):
```python
# Session-scoped state. Keyed by session id for isolation.
_mcp_session_kits: dict[int, dict[str, typing.Any]] = {}
_mcp_session_designs: dict[int, dict[str, typing.Any]] = {}
_mcp_session_types: dict[int, dict[str, typing.Any]] = {}
_mcp_session_kit_mode: dict[int, str] = {}
_mcp_session_kit_source: dict[int, str] = {}
_mcp_session_transactions: dict[int, Transaction] = {}
_mcp_session_transaction_rollback: set[int] = set()
_mcp_session_selection: dict[int, dict[str, list[str]]] = {}
_mcp_session_camera: dict[int, dict[str, typing.Any]] = {}
```

#### App Constants (lines 2946-2948):
```python
_APP_RESOURCE_URI = "ui://compose/design-viewer"
_APP_HTML_PATH = os.path.join(os.path.dirname(__file__), "dist", "mcp-app.html")
```

#### Key Helper Functions:

**_build_kit_artifact_data()** - Builds kit artifact payload for UI selection:
- Extracts designs, types, and connector ports from kit
- Returns formatted data structure for KitArtifactSelect UI

**_build_diagram_data()** (lines 2985-3100):
- Computes pre-rendered diagram points and lines from kit/design data
- Flattens design using `flattenDesignDict(kit, design_guid)`
- Extracts piece centers and positions
- Builds connection lines with diff status ("default", "added", "removed", "modified")
- Returns `{"points": [], "lines": []}`

**_build_app_response()** (lines 3101-3120):
- Builds MCP Apps protocol tool response with pre-computed diagram data as JSON text
- Sets capabilities based on mode (pieceSelection, connectionSelection)
- Applies kit artifact data
- Returns JSON string of diagram data

#### MCP App Tools (8 tools, lines 3122-3225)

All tools:
- Use `@mcp.tool()` decorator with `meta={"ui": {"resourceUri": "ui://compose/design-viewer"}}`
- Call `_build_app_response()` with different modes
- Return JSON strings with pre-computed diagram data

```python
@mcp.resource(_APP_RESOURCE_URI, mime_type="text/html;profile=mcp-app")
def design_viewer_resource() -> str:
    """Serve the MCP App design viewer HTML"""

@mcp.tool(meta={"ui": {"resourceUri": _APP_RESOURCE_URI}})
def show_design(ctx: Context) -> str:
    """Show the current design as a 2D diagram"""

@mcp.tool(meta={"ui": {"resourceUri": _APP_RESOURCE_URI}})
def show_diagram(ctx: Context) -> str:
    """Show diagram only"""

@mcp.tool(meta={"ui": {"resourceUri": _APP_RESOURCE_URI}})
def show_scene(ctx: Context) -> str:
    """Show as scene (2D in MCP)"""

@mcp.tool(meta={"ui": {"resourceUri": _APP_RESOURCE_URI}})
def show_diff(ctx: Context, design_diff: dict | None = None) -> str:
    """Show diff with coloring"""

@mcp.tool(meta={"ui": {"resourceUri": _APP_RESOURCE_URI}})
def show_diagram_diff(ctx: Context, design_diff: dict | None = None) -> str:
    """Show diagram diff"""

@mcp.tool(meta={"ui": {"resourceUri": _APP_RESOURCE_URI}})
def select_pieces(ctx: Context) -> str:
    """Piece selection view"""

@mcp.tool(meta={"ui": {"resourceUri": _APP_RESOURCE_URI}})
def select_connections(ctx: Context) -> str:
    """Connection selection view"""

@mcp.tool(meta={"ui": {"resourceUri": _APP_RESOURCE_URI}})
def select_pieces_and_connections(ctx: Context) -> str:
    """Combined selection view"""
```

### 6. **compose/ui MCP Design Viewer Component** - [compose/ui/index.tsx](compose/ui/index.tsx) (lines 1990-2227)

```typescript
// #region 🔖McpApp
// Specs: MCP App design viewer component using official @modelcontextprotocol/ext-apps/react

interface McpDiagramPoint {
  guid: string;
  id: string;
  u: number;
  v: number;
  status: "default" | "removed" | "added" | "modified";
}

interface McpDiagramLine {
  guid: string;
  sourceU: number;
  sourceV: number;
  targetU: number;
  targetV: number;
  status: "default" | "removed" | "added" | "modified";
}

export interface McpDiagramPayload {
  points: McpDiagramPoint[];
  lines: McpDiagramLine[];
  capabilities?: {
    pieceSelection?: boolean;
    connectionSelection?: boolean;
  };
}

export const McpDesignViewer: React.FC = () => {
  // Uses useApp from @modelcontextprotocol/ext-apps/react
  // Receives tool results and renders ComposeDiagram with payload data
  // Sends selection changes back via updateModelContext
};

export const mountMcpDesignViewer = (createRoot: ...) => {
  // Mount helper for standalone app
};
```

## Protocol Overview

**Resource URI**: `ui://compose/design-viewer`

**Tool Response Format** (JSON text content):
```json
{
  "points": [
    {
      "guid": "string",
      "id": "string", 
      "u": number,
      "v": number,
      "status": "default|added|modified|removed"
    }
  ],
  "lines": [
    {
      "guid": "string",
      "sourceU": number,
      "sourceV": number,
      "targetU": number,
      "targetV": number,
      "status": "default|added|modified|removed"
    }
  ],
  "capabilities": {
    "pieceSelection": boolean,
    "connectionSelection": boolean
  },
  "kitArtifacts": {
    "designs": [...],
    "types": [...],
    "ports": [...]
  }
}
```

**Selection Updates** (back to host via updateModelContext):
```json
{
  "selectionChange": {
    "pieceGuids": ["..."],
    "connectionGuids": ["..."]
  }
}
```

## Key Architecture Details

1. **Session Management**: Per-session state isolated by `id(ctx.session)`
2. **Resource-first**: Pre-computes all diagram data server-side to minimize bandwidth
3. **CSP-compliant**: Custom Zod JIT disable plugin prevents eval() calls
4. **Lightweight**: 322KB bundle (~95KB gzip) with only React + MCP SDK
5. **Standalone**: mcp-app.tsx has no @compose/ui, @semio-tech/compose-js, or Three.js dependencies
6. **Protocol**: Follows official MCP Apps protocol with resourceUri + tool metadata

