console.log("[DEBUG] McpDesignViewer rendering");
const { app, isConnected, error } = useApp({
  appInfo: { name: "compose design viewer", version: "1.0.0" },
  capabilities: {},
  onAppCreated: (a: McpAppInstance) => {
    console.log("[DEBUG] onAppCreated called", a);
    appRef.current = a;
    a.ontoolresult = (result: unknown) => {
      console.log("[DEBUG] ontoolresult received:", JSON.stringify(result).slice(0, 500));
